/* Design System Page - Using correct token names */

/* ============================================
   BLUR BACKGROUND
   ============================================ */
.blur-container {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 450px;
  overflow: hidden;
  pointer-events: none;
  z-index: -1;
}

.blur-container::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 450px;
  background: linear-gradient\(to bottom, transparent 0%, var\(--color-bg-page-primary\) 100%\);
  pointer-events: none;
  z-index: 1;
}

.blur-ellipse {
  position: absolute;
  border-radius: 50%;
  filter: blur\(80px\);
  opacity: 0.15;
  animation: floatCloud 16s ease-in-out infinite;
  will-change: transform;
}

@keyframes floatCloud {
  0%, 100% { transform: translate\(0, 0\) scale\(1\); }
  25% { transform: translate\(150px, -100px\) scale\(1.1\); }
  50% { transform: translate\(-130px, 90px\) scale\(0.9\); }
  75% { transform: translate\(100px, 140px\) scale\(1.05\); }
}

